1	<!DOCTYPE html>
2	<html lang="en" data-theme="dark">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
6	  <title>Hazard Studio — Data Entry Blocks</title>
7	  <link rel="preconnect" href="https://fonts.googleapis.com">
8	  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap">
10	  <style>
11	    /* ==========================================================================
12	       HAZARD STUDIO — DATA ENTRY BLOCKS & TREEVIEW CODEX
13	       Adhering strictly to RAW_RULE.md | Single-Active-Branch Accordion Tree
14	       ========================================================================== */
15	    :root {
16	      --bg-canvas:        #080706;
17	      --bg-card:          #13100d;
18	      --bg-card-hover:    #1c1713;
19	      --bg-input:         #1a1511;
20	      --bg-input-focus:   #231c16;
21	
22	      --text-vivid:       #fffcf7;
23	      --text-main:        #ede4d8;
24	      --text-muted:       #8a7b6c;
25	      --text-dim:         #5c5044;
26	
27	      --border-dim:       #292018;
28	      --border-mid:       #3f3226;
29	      --border-bright:    #634f3c;
30	
31	      --accent:           #ff9e1b;
32	      --accent-hover:     #ffb03a;
33	      --accent-glow:      rgba(255, 158, 27, 0.25);
34	      --accent-bg:        rgba(255, 158, 27, 0.12);
35	      --accent-border:    rgba(255, 158, 27, 0.4);
36	
37	      --hazard-low:       #10b981;
38	      --hazard-med:       #f59e0b;
39	      --hazard-high:      #f43f5e;
40	      --hazard-crit:      #d946ef;
41	
42	      --radius-sm:        6px;
43	      --radius-md:        10px;
44	      --radius-lg:        14px;
45	      --shadow-subtle:    0 4px 20px rgba(0, 0, 0, 0.5);
46	
47	      color-scheme: dark;
48	      font-family: "IBM Plex Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
49	      font-size: 14.5px;
50	      line-height: 1.5;
51	    }
52	
53	    :root[data-theme="light"] {
54	      --bg-canvas:        #f5f3ef;
55	      --bg-card:          #ffffff;
56	      --bg-card-hover:    #f9f7f4;
57	      --bg-input:         #f0ebe3;
58	      --bg-input-focus:   #ffffff;
59	
60	      --text-vivid:       #18130e;
61	      --text-main:        #2c231a;
62	      --text-muted:       #6b5a49;
63	      --text-dim:         #9e8c79;
64	
65	      --border-dim:       #ded5c7;
66	      --border-mid:       #c5b8a5;
67	      --border-bright:    #8f7d67;
68	
69	      --accent:           #d97706;
70	      --accent-hover:     #b45309;
71	      --accent-glow:      rgba(217, 119, 6, 0.2);
72	      --accent-bg:        rgba(217, 119, 6, 0.1);
73	      --accent-border:    rgba(217, 119, 6, 0.4);
74	
75	      color-scheme: light;
76	    }
77	
78	    * { box-sizing: border-box; margin: 0; padding: 0; }
79	    html, body { min-height: 100%; }
80	
81	    body {
82	      background: var(--bg-canvas);
83	      color: var(--text-main);
84	      padding: 2rem 1.5rem 4rem;
85	      display: flex;
86	      justify-content: center;
87	    }
88	
89	    .app-container {
90	      width: 100%;
91	      max-width: 1380px;
92	      display: flex;
93	      flex-direction: column;
94	      gap: 2rem;
95	    }
96	
97	    /* Top Navigation */
98	    .top-bar {
99	      display: flex;
100	      justify-content: space-between;
101	      align-items: center;
102	      border-bottom: 1px solid var(--border-dim);
103	      padding-bottom: 1.25rem;
104	      flex-wrap: wrap;
105	      gap: 1rem;
106	    }
107	
108	    .title-stack h1 {
109	      font-size: 1.5rem;
110	      font-weight: 700;
111	      color: var(--text-vivid);
112	      letter-spacing: -0.02em;
113	      display: flex;
114	      align-items: center;
115	      gap: 0.6rem;
116	    }
117	
118	    .title-stack h1::before {
119	      content: "";
120	      width: 12px;
121	      height: 12px;
122	      border-radius: 3px;
123	      background: var(--accent);
124	      box-shadow: 0 0 10px var(--accent);
125	    }
126	
127	    .title-stack p {
128	      font-size: 0.88rem;
129	      color: var(--text-muted);
130	      margin-top: 0.2rem;
131	    }
132	
133	    .header-actions {
134	      display: flex;
135	      align-items: center;
136	      gap: 0.75rem;
137	    }
138	
139	    .btn-action {
140	      background: var(--bg-card);
141	      border: 1px solid var(--border-mid);
142	      color: var(--text-main);
143	      padding: 0.5rem 0.9rem;
144	      border-radius: var(--radius-sm);
145	      font-size: 0.85rem;
146	      font-weight: 600;
147	      cursor: pointer;
148	      transition: all 0.15s ease;
149	      display: inline-flex;
150	      align-items: center;
151	      gap: 0.4rem;
152	    }
153	
154	    .btn-action:hover {
155	      background: var(--bg-card-hover);
156	      border-color: var(--accent);
157	      color: var(--accent);
158	    }
159	
160	    .btn-action.btn-primary {
161	      background: var(--accent);
162	      border-color: var(--accent);
163	      color: #080706;
164	    }
165	
166	    .btn-action.btn-primary:hover {
167	      background: var(--accent-hover);
168	      box-shadow: 0 0 12px var(--accent-glow);
169	    }
170	
171	    /* 2-Column Split: Controls vs Live JSON Inspector */
172	    .workspace-grid {
173	      display: grid;
174	      grid-template-columns: minmax(0, 1.35fr) minmax(380px, 0.9fr);
175	      gap: 1.75rem;
176	      align-items: start;
177	    }
178	
179	    @media (max-width: 990px) {
180	      .workspace-grid { grid-template-columns: 1fr; }
181	    }
182	
183	    .blocks-stream {
184	      display: flex;
185	      flex-direction: column;
186	      gap: 1.5rem;
187	    }
188	
189	    /* Card Box */
190	    .entry-block {
191	      background: var(--bg-card);
192	      border: 1px solid var(--border-dim);
193	      border-radius: var(--radius-lg);
194	      overflow: visible;
195	      box-shadow: var(--shadow-subtle);
196	      transition: border-color 0.2s ease;
197	    }
198	
199	    .entry-block:hover {
200	      border-color: var(--border-mid);
201	    }
202	
203	    .block-header {
204	      padding: 1rem 1.25rem;
205	      background: rgba(255, 255, 255, 0.02);
206	      border-bottom: 1px solid var(--border-dim);
207	      display: flex;
208	      justify-content: space-between;
209	      align-items: center;
210	      border-radius: var(--radius-lg) var(--radius-lg) 0 0;
211	    }
212	
213	    .block-tag {
214	      font-family: "JetBrains Mono", monospace;
215	      font-size: 0.75rem;
216	      font-weight: 700;
217	      color: var(--accent);
218	      text-transform: uppercase;
219	      letter-spacing: 0.05em;
220	      background: var(--accent-bg);
221	      padding: 0.2rem 0.5rem;
222	      border-radius: 4px;
223	      border: 1px solid var(--accent-border);
224	    }
225	
226	    .block-title {
227	      font-size: 0.95rem;
228	      font-weight: 600;
229	      color: var(--text-vivid);
230	    }
231	
232	    .block-body {
233	      padding: 1.25rem;
234	      display: flex;
235	      flex-direction: column;
236	      gap: 1.1rem;
237	    }
238	
239	    .field-label {
240	      display: flex;
241	      justify-content: space-between;
242	      align-items: center;
243	      font-size: 0.82rem;
244	      font-weight: 600;
245	      color: var(--text-muted);
246	      margin-bottom: 0.35rem;
247	    }
248	
249	    .field-hint {
250	      font-size: 0.75rem;
251	      color: var(--text-dim);
252	      font-family: "JetBrains Mono", monospace;
253	    }
254	
255	    /* --------------------------------------------------------------------------
256	       1. RAW TEXT INPUT & PROMPT TEXTAREA
257	       -------------------------------------------------------------------------- */
258	    .raw-input-box {
259	      width: 100%;
260	      height: 48px;
261	      background: var(--bg-input);
262	      border: 1px solid var(--border-dim);
263	      border-radius: var(--radius-sm);
264	      color: var(--text-vivid);
265	      font-family: inherit;
266	      font-size: 0.95rem;
267	      padding: 0 1rem;
268	      outline: none;
269	      transition: all 0.15s ease;
270	    }
271	
272	    .raw-input-box:focus {
273	      background: var(--bg-input-focus);
274	      border-color: var(--accent);
275	      box-shadow: 0 0 0 3px var(--accent-glow);
276	    }
277	
278	    .raw-textarea-box {
279	      width: 100%;
280	      min-height: 110px;
281	      background: var(--bg-input);
282	      border: 1px solid var(--border-dim);
283	      border-radius: var(--radius-sm);
284	      color: var(--text-vivid);
285	      font-family: "JetBrains Mono", monospace;
286	      font-size: 0.88rem;
287	      padding: 0.85rem 1rem;
288	      outline: none;
289	      resize: vertical;
290	      line-height: 1.6;
291	      transition: all 0.15s ease;
292	    }
293	
294	    .raw-textarea-box:focus {
295	      background: var(--bg-input-focus);
296	      border-color: var(--accent);
297	      box-shadow: 0 0 0 3px var(--accent-glow);
298	    }
299	
300	    /* --------------------------------------------------------------------------
301	       2. RAW SEARCHER (Instant Command Bar)
302	       -------------------------------------------------------------------------- */
303	    .searcher-monolith {
304	      width: 100%;
305	      height: 56px;
306	      background: var(--bg-input);
307	      border: 1px solid var(--border-mid);
308	      border-radius: var(--radius-md);
309	      display: flex;
310	      align-items: center;
311	      padding: 0 1rem;
312	      gap: 0.75rem;
313	      transition: all 0.2s ease;
314	    }
315	
316	    .searcher-monolith:focus-within {
317	      background: var(--bg-input-focus);
318	      border-color: var(--accent);
319	      box-shadow: 0 0 0 3px var(--accent-glow);
320	    }
321	
322	    .searcher-icon {
323	      color: var(--accent);
324	      font-size: 1.1rem;
325	      flex-shrink: 0;
326	    }
327	
328	    .searcher-input {
329	      width: 100%;
330	      height: 100%;
331	      background: transparent;
332	      border: none;
333	      outline: none;
334	      color: var(--text-vivid);
335	      font-size: 1rem;
336	      font-family: inherit;
337	    }
338	
339	    .searcher-clear {
340	      background: rgba(255, 255, 255, 0.08);
341	      border: none;
342	      color: var(--text-muted);
343	      width: 26px;
344	      height: 26px;
345	      border-radius: 50%;
346	      display: flex;
347	      align-items: center;
348	      justify-content: center;
349	      cursor: pointer;
350	      font-size: 0.8rem;
351	      transition: all 0.15s ease;
352	    }
353	
354	    .searcher-clear:hover {
355	      background: var(--hazard-high);
356	      color: #fff;
357	    }
358	
359	    .search-active-banner {
360	      display: flex;
361	      align-items: center;
362	      justify-content: space-between;
363	      gap: 0.6rem;
364	      padding: 0.5rem 0.85rem;
365	      background: var(--accent-bg);
366	      border: 1px solid var(--accent-border);
367	      border-radius: var(--radius-sm);
368	      font-size: 0.82rem;
369	      margin-bottom: 0.5rem;
370	    }
371	
372	    .active-badge-tag {
373	      font-family: "JetBrains Mono", monospace;
374	      font-size: 0.68rem;
375	      font-weight: 700;
376	      color: var(--accent);
377	      background: rgba(0, 242, 254, 0.15);
378	      border: 1px solid var(--accent-border);
379	      padding: 0.15rem 0.45rem;
380	      border-radius: 4px;
381	      display: inline-flex;
382	      align-items: center;
383	      gap: 0.3rem;
384	    }
385	
386	    .active-target-title {
387	      color: var(--text-vivid);
388	      font-weight: 600;
389	      font-family: inherit;
390	    }
391	
392	    .search-results-list {
393	      display: flex;
394	      flex-direction: column;
395	      gap: 0.4rem;
396	      max-height: 190px;
397	      overflow-y: auto;
398	      padding-right: 4px;
399	    }
400	
401	    .search-result-item {
402	      padding: 0.65rem 0.85rem;
403	      background: var(--bg-input);
404	      border: 1px solid var(--border-dim);
405	      border-radius: var(--radius-sm);
406	      display: flex;
407	      justify-content: space-between;
408	      align-items: center;
409	      font-size: 0.88rem;
410	      cursor: pointer;
411	      transition: all 0.15s cubic-bezier(0.16, 1, 0.3, 1);
412	    }
413	
414	    .search-result-item:hover {
415	      background: var(--bg-card-hover);
416	      border-color: var(--border-mid);
417	      transform: translateY(-1px);
418	    }
419	
420	    .search-result-item.selected {
421	      background: var(--accent-bg);
422	      border-color: var(--accent-border);
423	      box-shadow: inset 3px 0 0 var(--accent);
424	    }
425	
426	    .search-result-item.selected .search-result-name {
427	      color: var(--accent);
428	      font-weight: 700;
429	    }
430	
431	    .selected-pill-badge {
432	      font-family: "JetBrains Mono", monospace;
433	      font-size: 0.68rem;
434	      font-weight: 700;
435	      color: var(--accent);
436	      background: rgba(0, 242, 254, 0.15);
437	      border: 1px solid var(--accent-border);
438	      padding: 0.15rem 0.45rem;
439	      border-radius: 4px;
440	      display: inline-flex;
441	      align-items: center;
442	      gap: 0.25rem;
443	    }
444	
445	    /* --------------------------------------------------------------------------
446	       3. NOTION-STYLE DROPDOWN SELECTOR (Single Select + Persistent Suggestions)
447	       -------------------------------------------------------------------------- */
448	    .notion-combobox-wrap {
449	      position: relative;
450	    }
451	
452	    .notion-combobox-trigger {
453	      width: 100%;
454	      min-height: 48px;
455	      background: var(--bg-input);
456	      border: 1px solid var(--border-dim);
457	      border-radius: var(--radius-sm);
458	      padding: 0.4rem 0.85rem;
459	      display: flex;
460	      align-items: center;
461	      justify-content: space-between;
462	      cursor: pointer;
463	      transition: all 0.15s ease;
464	    }
465	
466	    .notion-combobox-trigger:hover,
467	    .notion-combobox-trigger.active {
468	      border-color: var(--accent);
469	      box-shadow: 0 0 0 2px var(--accent-glow);
470	    }
471	
472	    .selected-val-badge {
473	      display: inline-flex;
474	      align-items: center;
475	      gap: 0.4rem;
476	      background: var(--accent-bg);
477	      color: var(--accent);
478	      border: 1px solid var(--accent-border);
479	      padding: 0.25rem 0.65rem;
480	      border-radius: 4px;
481	      font-weight: 600;
482	      font-size: 0.85rem;
483	    }
484	
485	    .combobox-chevron {
486	      color: var(--text-muted);
487	      font-size: 0.8rem;
488	      transition: transform 0.2s ease;
489	    }
490	
491	    .notion-combobox-trigger.active .combobox-chevron {
492	      transform: rotate(180deg);
493	      color: var(--accent);
494	    }
495	
496	    .notion-dropdown-menu {
497	      position: absolute;
498	      top: calc(100% + 6px);
499	      left: 0;
500	      right: 0;
501	      background: var(--bg-card);
502	      border: 1px solid var(--border-bright);
503	      border-radius: var(--radius-md);
504	      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8);
505	      z-index: 100;
506	      overflow: hidden;
507	      display: none;
508	      flex-direction: column;
509	    }
510	
511	    .notion-dropdown-menu.open {
512	      display: flex;
513	    }
514	
515	    .dropdown-search-wrap {
516	      padding: 0.6rem;
517	      border-bottom: 1px solid var(--border-dim);
518	      background: var(--bg-input);
519	    }
520	
521	    .dropdown-search-input {
522	      width: 100%;
523	      height: 38px;
524	      background: var(--bg-card);
525	      border: 1px solid var(--border-mid);
526	      border-radius: 4px;
527	      padding: 0 0.75rem;
528	      color: var(--text-vivid);
529	      font-size: 0.88rem;
530	      outline: none;
531	    }
532	
533	    .dropdown-search-input:focus {
534	      border-color: var(--accent);
535	    }
536	
537	    .dropdown-group-header {
538	      font-family: "JetBrains Mono", monospace;
539	      font-size: 0.68rem;
540	      font-weight: 700;
541	      color: var(--text-dim);
542	      text-transform: uppercase;
543	      letter-spacing: 0.05em;
544	      padding: 0.4rem 0.65rem 0.25rem;
545	      background: rgba(255, 255, 255, 0.02);
546	      border-bottom: 1px solid var(--border-dim);
547	      margin-top: 0.2rem;
548	    }
549	
550	    .dropdown-group-header:first-child {
551	      margin-top: 0;
552	    }
553	
554	    .dropdown-options-list {
555	      max-height: 220px;
556	      overflow-y: auto;
557	      padding: 0.4rem;
558	      display: flex;
559	      flex-direction: column;
560	      gap: 2px;
561	    }
562	
563	    .dropdown-opt-row {
564	      padding: 0.5rem 0.75rem;
565	      border-radius: 4px;
566	      font-size: 0.88rem;
567	      color: var(--text-main);
568	      cursor: pointer;
569	      display: flex;
570	      justify-content: space-between;
571	      align-items: center;
572	      transition: background 0.1s ease;
573	      gap: 0.5rem;
574	    }
575	
576	    .dropdown-opt-row:hover,
577	    .dropdown-opt-row.selected {
578	      background: var(--bg-input-focus);
579	      color: var(--accent);
580	    }
581	
582	    .opt-label-group {
583	      display: flex;
584	      align-items: center;
585	      gap: 0.5rem;
586	      min-width: 0;
587	      flex: 1 1 auto;
588	    }
589	
590	    .opt-delete-btn {
591	      background: transparent;
592	      border: 1px solid transparent;
593	      color: var(--text-dim);
594	      width: 24px;
595	      height: 24px;
596	      border-radius: 4px;
597	      display: flex;
598	      align-items: center;
599	      justify-content: center;
600	      font-size: 0.75rem;
601	      cursor: pointer;
602	      transition: all 0.15s ease;
603	      flex-shrink: 0;
604	    }
605	
606	    .opt-delete-btn:hover {
607	      background: rgba(244, 63, 94, 0.18);
608	      border-color: rgba(244, 63, 94, 0.4);
609	      color: #fb7185;
610	    }
611	
612	    .dropdown-create-row {
613	      padding: 0.65rem 0.75rem;
614	      background: var(--accent-bg);
615	      border-top: 1px solid var(--accent-border);
616	      color: var(--accent);
617	      font-size: 0.85rem;
618	      font-weight: 600;
619	      cursor: pointer;
620	      display: flex;
621	      align-items: center;
622	      gap: 0.5rem;
623	      transition: background 0.15s ease;
624	    }
625	
626	    .dropdown-create-row:hover {
627	      background: var(--accent);
628	      color: #080706;
629	    }
630	
631	    /* --------------------------------------------------------------------------
632	       4. NOTION-STYLE DROPDOWN MULTI-SELECT (Tag Pool Suggestors + Create)
633	       -------------------------------------------------------------------------- */
634	    .multi-select-host {
635	      position: relative;
636	      display: flex;
637	      flex-direction: column;
638	      gap: 0.5rem;
639	    }
640	
641	    .multi-tag-box {
642	      width: 100%;
643	      min-height: 52px;
644	      background: var(--bg-input);
645	      border: 1px solid var(--border-dim);
646	      border-radius: var(--radius-sm);
647	      padding: 0.4rem 0.65rem;
648	      display: flex;
649	      flex-wrap: wrap;
650	      align-items: center;
651	      gap: 0.45rem;
652	      cursor: text;
653	      transition: all 0.15s ease;
654	    }
655	
656	    .multi-tag-box:focus-within,
657	    .multi-tag-box.active {
658	      background: var(--bg-input-focus);
659	      border-color: var(--accent);
660	      box-shadow: 0 0 0 3px var(--accent-glow);
661	    }
662	
663	    .tag-chip {
664	      background: var(--bg-card);
665	      border: 1px solid var(--border-bright);
666	      color: var(--text-vivid);
667	      font-size: 0.82rem;
668	      font-weight: 600;
669	      padding: 0.25rem 0.55rem;
670	      border-radius: 4px;
671	      display: inline-flex;
672	      align-items: center;
673	      gap: 0.4rem;
674	    }
675	
676	    .tag-chip.accent {
677	      background: var(--accent-bg);
678	      color: var(--accent);
679	      border-color: var(--accent-border);
680	    }
681	
682	    .tag-chip-remove {
683	      cursor: pointer;
