2582	    /* --------------------------------------------------------------------------
2583	       7. MARKDOWN / TREEVIEW OUTLINER (Single-Path Isolation & (n+3) Depth Clamping)
2584	       Law:
2585	       - Chosen H_n: Shows ONLY H1..H_{n-1} ancestors leading to H_n (all ancestor siblings hidden).
2586	       - Shows ALL H_{n+1} children of H_n and all descendants down to H_{n+3} (max n+3 traversal).
2587	       - Sub-branches deeper than H_{n+3} are pruned with an interactive expansion banner.
2588	       -------------------------------------------------------------------------- */
2589	    function findNodeById(nodes, id) {
2590	      for (const node of nodes) {
2591	        if (node.id === id) return node;
2592	        if (node.children && node.children.length > 0) {
2593	          const found = findNodeById(node.children, id);
2594	          if (found) return found;
2595	        }
2596	      }
2597	      return null;
2598	    }
2599	
2600	    function getActivePath(nodes, targetId, currentPath = []) {
2601	      for (const node of nodes) {
2602	        const nextPath = [...currentPath, node];
2603	        if (node.id === targetId) return nextPath;
2604	        if (node.children && node.children.length > 0) {
2605	          const res = getActivePath(node.children, targetId, nextPath);
2606	          if (res) return res;
2607	        }
2608	      }
2609	      return null;
2610	    }
